1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Beaver prototype</title>
7	<!--
8	  Mac prototype client for the /ws protocol in docs/contracts.md: mic, screen sharing,
9	  mascot voice and cards. Stands in for the iPhone app (WP1) so the idea can be tried on
10	  a Mac. Open http://localhost:8000/#token=<APP_TOKEN> in desktop Chrome.
11	-->
12	<style>
13	  :root {
14	    --bg: #f6f5f2; --panel: #fff; --ink: #1d1d1b; --muted: #6b6a66; --line: #e4e2dc;
15	    --red: #d6001c; --idle: #b9b6ad; --listening: #1f8a4c; --thinking: #6b5bd6;
16	    --searching: #d08a00; --speaking: #d6001c;
17	  }
18	  @media (prefers-color-scheme: dark) {
19	    :root { --bg: #151514; --panel: #1f1f1d; --ink: #f1efe9; --muted: #a09d95; --line: #33322f; }
20	  }
21	  * { box-sizing: border-box; }
22	  body { margin: 0; background: var(--bg); color: var(--ink);
23	         font: 15px/1.4 -apple-system, BlinkMacSystemFont, "Helvetica Neue", sans-serif; }
24	  main { max-width: 760px; margin: 0 auto; padding: 24px 16px 48px; display: grid; gap: 16px; }
25	  header { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; justify-content: space-between; }
26	  h1 { font-size: 18px; margin: 0; }
27	  .row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
28	  button, select, input { font: inherit; color: inherit; }
29	  button { border: 1px solid var(--line); background: var(--panel); border-radius: 999px;
30	           padding: 6px 14px; cursor: pointer; }
31	  button:disabled { opacity: .5; cursor: default; }
32	  .pill { font-size: 12px; color: var(--muted); border: 1px solid var(--line); border-radius: 999px; padding: 2px 10px; }
33	  .pill.ok { color: var(--listening); border-color: currentColor; }
34	  .stage { display: grid; justify-items: center; gap: 10px; padding: 24px 0 8px; }
35	  #orb { width: 132px; height: 132px; border-radius: 50%; border: none; background: var(--idle);
36	         box-shadow: 0 0 0 0 transparent; transition: background .2s, transform .15s; touch-action: none; }
37	  #orb:active { transform: scale(.96); }
38	  #orb[data-state="listening"] { background: var(--listening); animation: pulse 1.2s infinite; }
39	  #orb[data-state="thinking"] { background: var(--thinking); animation: pulse 1.6s infinite; }
40	  #orb[data-state="searching"] { background: var(--searching); animation: pulse .9s infinite; }
41	  #orb[data-state="speaking"] { background: var(--speaking); animation: pulse .7s infinite; }
42	  @keyframes pulse { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 0%, transparent); }
43	                     50% { box-shadow: 0 0 0 14px rgb(0 0 0 / .06); } 100% { box-shadow: 0 0 0 0 transparent; } }
44	  @media (prefers-reduced-motion: reduce) { #orb { animation: none !important; } }
45	  #label { color: var(--muted); min-height: 1.4em; }
46	  .hint { color: var(--muted); font-size: 13px; text-align: center; }
47	  .bubble { background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 12px 16px; }
48	  .you { color: var(--muted); }
49	  #cards { display: grid; gap: 12px; }
50	  .card { background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 14px 16px; display: grid; gap: 4px; }
51	  .card .kind { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
52	  .card .big { font-size: 26px; font-weight: 650; font-variant-numeric: tabular-nums; }
53	  .card .meta { color: var(--muted); }
54	  .badge { display: inline-block; background: var(--red); color: #fff; border-radius: 6px; padding: 0 6px; font-weight: 600; }
55	  .verdict-fits { color: var(--listening); } .verdict-tight { color: var(--searching); } .verdict-clash { color: var(--red); }
56	  #screenThumb { max-width: 160px; border-radius: 8px; border: 1px solid var(--line); display: none; }
57	  #log { font: 12px/1.5 ui-monospace, Menlo, monospace; color: var(--muted); white-space: pre-wrap;
58	         max-height: 180px; overflow: auto; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 8px 10px; }
59	  form { display: flex; gap: 8px; } form input { flex: 1; min-width: 0; border: 1px solid var(--line);
60	         background: var(--panel); border-radius: 999px; padding: 6px 14px; }
61	</style>
62	</head>
63	<body>
64	<main>
65	  <header>
66	    <h1>Beaver prototype</h1>
67	    <div class="row">
68	      <span id="conn" class="pill">disconnected</span>
69	      <select id="mode" title="Voice mode">
70	        <option value="ptt">Push to talk</option>
71	        <option value="handsfree">Hands-free (use headphones)</option>
72	      </select>
73	      <button id="share">Share screen</button>
74	      <button id="sendScreen" disabled>Send screen now</button>
75	    </div>
76	  </header>
77	
78	  <section class="stage">
79	    <button id="orb" data-state="idle" aria-label="Hold to talk"></button>
80	    <div id="label"></div>
81	    <div class="hint" id="hint">Click the orb to start. Then hold it, or hold Space, while you talk.</div>
82	  </section>
83	
84	  <div class="row"><img id="screenThumb" alt="Last screen frame sent"><span id="screenSummary" class="pill" hidden></span></div>
85	  <div id="you" class="you"></div>
86	  <div id="say" class="bubble" hidden></div>
87	  <div id="cards"></div>
88	
89	  <form id="textForm"><input id="text" placeholder="Or type a question…" autocomplete="off"><button>Send</button></form>
90	  <div id="log"></div>
91	</main>
92	
93	<script>
94	"use strict";
95	const RATE = 24000, CHUNK = 1920; // 80 ms of 24 kHz mono, contracts § Audio
96	const $ = (id) => document.getElementById(id);
97	const log = (...a) => { const l = $("log"); l.textContent += a.join(" ") + "\n"; l.scrollTop = l.scrollHeight; };
98	
99	// Token: from #token=... once, then remembered.
100	let token = new URLSearchParams(location.hash.slice(1)).get("token");
101	try {
102	  if (token) { localStorage.setItem("beaverToken", token); history.replaceState(null, "", location.pathname); }
103	  else token = localStorage.getItem("beaverToken");
104	} catch {}
105	if (!token) token = prompt("APP_TOKEN (from backend/.env)") || "";
106	
107	let ws, ctx, micNode, screenStream, screenVideo;
108	let mode = "ptt", talking = false, serverState = "idle", dropAudio = false;
109	let playing = [], nextTime = 0, releasedAt = 0, firstAudioLogged = true;
110	
111	// ---------- WebSocket ----------
112	function connect() {
113	  ws = new WebSocket(`${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/ws`);
114	  ws.onopen = () => ws.send(JSON.stringify({ type: "hello", token, mode }));
115	  ws.onclose = (e) => {
116	    setConn(e.code === 1008 ? "bad token" : "disconnected", false);
117	    if (e.code === 1008) { try { localStorage.removeItem("beaverToken"); } catch {} return; }
118	    setTimeout(connect, 1000);
119	  };
120	  ws.onmessage = (e) => onMessage(JSON.parse(e.data));
121	}
122	const send = (m) => ws && ws.readyState === 1 && ws.send(JSON.stringify(m));
123	function setConn(text, ok) { $("conn").textContent = text; $("conn").classList.toggle("ok", ok); }
124	
125	function onMessage(m) {
126	  switch (m.type) {
127	    case "ready": setConn(mode === "handsfree" ? "connected · hands-free" : "connected", true); break;
128	    case "state":
129	      serverState = m.state; $("label").textContent = m.label || "";
130	      if (m.state === "listening" && mode === "handsfree") { stopPlayback(); grabScreen("speech"); }
131	      renderOrb(); break;
132	    case "transcript": $("you").textContent = "You: " + m.text; log("transcript", JSON.stringify(m.text)); break;
133	    case "reply":
134	      dropAudio = false; firstAudioLogged = false;
135	      $("say").hidden = false; $("say").textContent = m.say; renderCards(m.cards || []); break;
136	    case "a2ui": log("a2ui", m.messages.length, "messages (rendered from reply.cards here)"); break;
137	    case "audio": if (!dropAudio) playChunk(m.data); break;
138	    case "audio_end": break;
139	    case "screen_ok":
140	      $("screenSummary").hidden = false;
141	      $("screenSummary").textContent = m.summary ? "Sees: " + m.summary : "Screen received (not read)";
142	      log("screen_ok", m.summary || "(no summary)"); break;
143	    case "error": log("error", m.message); $("label").textContent = m.message; break;
144	  }
145	}
146	
147	// ---------- Audio in ----------
148	const WORKLET = `class Pcm extends AudioWorkletProcessor {
149	  constructor() { super(); this.buf = new Int16Array(${CHUNK}); this.n = 0; }
150	  process(inputs) {
151	    const ch = inputs[0][0]; if (!ch) return true;
152	    for (let i = 0; i < ch.length; i++) {
153	      const s = Math.max(-1, Math.min(1, ch[i]));
154	      this.buf[this.n++] = s < 0 ? s * 0x8000 : s * 0x7fff;
155	      if (this.n === this.buf.length) { this.port.postMessage(this.buf.buffer, [this.buf.buffer]); this.buf = new Int16Array(${CHUNK}); this.n = 0; }
156	    }
157	    return true;
158	  }
159	}
160	registerProcessor("pcm", Pcm);`;
161	
162	function ensureCtx() { // needs a user gesture (click, key, submit) before audio can play
163	  if (!ctx) ctx = new AudioContext({ sampleRate: RATE }); // the browser resamples the mic to 24 kHz
164	  if (ctx.state === "suspended") ctx.resume();
165	}
166	
167	async function startAudio() {
168	  ensureCtx();
169	  await ctx.audioWorklet.addModule(URL.createObjectURL(new Blob([WORKLET], { type: "text/javascript" })));
170	  const mic = await navigator.mediaDevices.getUserMedia({
171	    audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
172	  });
173	  micNode = new AudioWorkletNode(ctx, "pcm");
174	  micNode.port.onmessage = (e) => { if (talking || mode === "handsfree") send({ type: "audio", data: b64(e.data) }); };
175	  ctx.createMediaStreamSource(mic).connect(micNode);
176	  $("hint").textContent = mode === "handsfree"
177	    ? "Hands-free: just talk. Talking over the beaver interrupts it."
178	    : "Hold the orb or Space while you talk. Click the orb while it speaks to stop it.";
179	  log("mic on at", ctx.sampleRate, "Hz");
180	}
181	
182	function b64(buf) {
183	  const bytes = new Uint8Array(buf); let s = "";
184	  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
185	  return btoa(s);
186	}
187	
188	// ---------- Audio out ----------
189	function playChunk(data) {
190	  if (!ctx) return;
191	  const raw = atob(data), n = raw.length >> 1, f = new Float32Array(n);
192	  for (let i = 0; i < n; i++) { const v = raw.charCodeAt(2 * i) | (raw.charCodeAt(2 * i + 1) << 8); f[i] = (v > 32767 ? v - 65536 : v) / 32768; }
193	  const buf = ctx.createBuffer(1, n, RATE); buf.copyToChannel(f, 0);
194	  const src = ctx.createBufferSource(); src.buffer = buf; src.connect(ctx.destination);
195	  nextTime = Math.max(nextTime, ctx.currentTime + 0.03);
196	  src.start(nextTime); nextTime += buf.duration;
197	  playing.push(src); src.onended = () => { playing = playing.filter((s) => s !== src); renderOrb(); };
198	  if (!firstAudioLogged && releasedAt) { firstAudioLogged = true; log(`first audio ${((performance.now() - releasedAt) / 1000).toFixed(2)} s after release`); }
199	  renderOrb();
200	}
201	
202	function stopPlayback() {
203	  dropAudio = true; // contracts § WebSocket: drop audio until the next reply
204	  for (const s of playing) { try { s.stop(); } catch {} }
205	  playing = []; nextTime = 0; renderOrb();
206	}
207	
208	function renderOrb() {
209	  const state = playing.length ? "speaking" : talking ? "listening" : serverState;
210	  $("orb").dataset.state = state;
211	}
212	
213	// ---------- Push to talk ----------
214	async function press() {
215	  if (!micNode) { await startAudio(); return; }      // first click only turns the mic on
216	  if (mode === "handsfree") { if (playing.length) { stopPlayback(); send({ type: "interrupt" }); } return; }
217	  if (talking) return;
218	  if (playing.length || serverState !== "idle") stopPlayback(); // the first audio frame interrupts server-side
219	  talking = true; renderOrb(); grabScreen("press");
220	}
221	function release() {
222	  if (!talking) return;
223	  talking = false; releasedAt = performance.now(); send({ type: "audio_end" }); renderOrb();
224	}
225	$("orb").addEventListener("pointerdown", (e) => { e.preventDefault(); press(); });
226	for (const ev of ["pointerup", "pointerleave", "pointercancel"]) $("orb").addEventListener(ev, release);
227	addEventListener("keydown", (e) => { if (e.code === "Space" && !e.repeat && document.activeElement !== $("text")) { e.preventDefault(); press(); } });
228	addEventListener("keyup", (e) => { if (e.code === "Space" && document.activeElement !== $("text")) { e.preventDefault(); release(); } });
229	
230	$("mode").addEventListener("change", () => {
231	  mode = $("mode").value; stopPlayback(); talking = false;
232	  if (ws) { ws.onclose = null; ws.close(); } connect();
233	  if (micNode) $("hint").textContent = mode === "handsfree" ? "Hands-free: just talk." : "Hold the orb or Space while you talk.";
234	});
235	
236	// ---------- Screen ----------
237	$("share").addEventListener("click", async () => {
238	  try {
239	    screenStream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 2 }, audio: false });
240	    screenVideo = Object.assign(document.createElement("video"), { srcObject: screenStream, muted: true });
241	    await screenVideo.play();
242	    screenStream.getVideoTracks()[0].onended = () => { screenStream = null; $("share").textContent = "Share screen"; $("sendScreen").disabled = true; };
243	    $("share").textContent = "Sharing ✓"; $("sendScreen").disabled = false;
244	    log("screen sharing on: a frame goes with each question");
245	  } catch (e) { log("screen share cancelled:", e.message); }
246	});
247	$("sendScreen").addEventListener("click", () => grabScreen("button"));
248	
249	let lastGrab = 0;
250	function grabScreen(why) {
251	  if (!screenVideo || !screenVideo.videoWidth || performance.now() - lastGrab < 1500) return;
252	  lastGrab = performance.now();
253	  const scale = Math.min(1, 1280 / screenVideo.videoWidth);
254	  const c = Object.assign(document.createElement("canvas"), {
255	    width: Math.round(screenVideo.videoWidth * scale), height: Math.round(screenVideo.videoHeight * scale) });
256	  c.getContext("2d").drawImage(screenVideo, 0, 0, c.width, c.height);
257	  const url = c.toDataURL("image/jpeg", 0.8);
258	  $("screenThumb").src = url; $("screenThumb").style.display = "block";
259	  send({ type: "screen", mime: "image/jpeg", data: url.split(",")[1] });
260	  log(`screen frame sent (${why}, ${c.width}x${c.height}, ${Math.round(url.length * 0.75 / 1024)} KB)`);
261	}
262	
263	// ---------- Text ----------
264	$("textForm").addEventListener("submit", (e) => {
265	  e.preventDefault(); const t = $("text").value.trim(); if (!t) return;
266	  ensureCtx(); stopPlayback(); grabScreen("text"); releasedAt = performance.now();
267	  send({ type: "text", text: t }); $("you").textContent = "You: " + t; $("text").value = "";
268	});
269	
270	// ---------- Cards (from reply.cards; the iPhone app renders the a2ui messages instead) ----------
271	const hm = (iso) => iso ? new Date(iso).toLocaleTimeString("de-CH", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Zurich" }) : "";
272	const day = (iso) => iso ? new Date(iso).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", timeZone: "Europe/Zurich" }) : "";
273	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
274	
275	function renderCards(cards) {
276	  $("cards").innerHTML = cards.map((c) => {
277	    if (c.kind === "train") return `<div class="card"><div class="kind">Train</div>
278	      <div class="big">${hm(c.departure)} → ${hm(c.arrival)}</div>
279	      <div>${esc(c.line)} · ${esc(c.from)} → ${esc(c.to)}</div>
280	      <div class="meta">${c.platform ? `Platform <span class="badge">${esc(c.platform)}</span> · ` : ""}${c.transfers ? c.transfers + " change(s)" : "direct"}${c.delay_min ? ` · <span class="verdict-clash">+${c.delay_min} min</span>` : ""}</div></div>`;
281	    if (c.kind === "conflict") return `<div class="card"><div class="kind">Plan check · <span class="verdict-${esc(c.verdict)}">${esc(c.verdict)}</span></div>
282	      <div><b>${esc(c.event?.title)}</b> ${day(c.event?.start)} ${hm(c.event?.start)}–${hm(c.event?.end)}</div>
283	      <div><b>${esc(c.proposal?.title)}</b> ${day(c.proposal?.start)} ${hm(c.proposal?.start)}${c.proposal?.place ? " · " + esc(c.proposal.place) : ""}</div>
284	      ${c.note ? `<div class="meta">${esc(c.note)}</div>` : ""}</div>`;
285	    if (c.kind === "event") return `<div class="card"><div class="kind">${c.source === "luma" ? "Luma event" : "Calendar"}</div>
286	      <div><b>${esc(c.title)}</b></div><div class="meta">${day(c.start)} ${hm(c.start)}–${hm(c.end)}${c.location ? " · " + esc(c.location) : ""}</div></div>`;
287	    if (c.kind === "flight") return `<div class="card"><div class="kind">Flight</div>
288	      <div class="big">${esc(c.from)} → ${esc(c.to)}</div>
289	      <div>${esc(c.flight_number)} · ${day(c.departure)} ${hm(c.departure)} → ${hm(c.arrival)}</div>
290	      ${c.booking_ref ? `<div class="meta">Booking ${esc(c.booking_ref)}</div>` : ""}</div>`;
291	    return `<div class="card"><pre>${esc(JSON.stringify(c, null, 2))}</pre></div>`;
292	  }).join("");
293	}
294	
295	connect();
296	</script>
297	</body>
298	</html>
