const vm = require("vm"), fs = require("fs"), assert = require("assert");
const src = fs.readFileSync(process.argv[2], "utf8");
const els = {}, handlers = {}, sent = [], timers = new Map();
let screen = "A", now = 10000, nextId = 1, track;
const el = (id) => els[id] ??= { id, textContent: "", style: {}, classList: { toggle() {} }, dataset: {},
  addEventListener: (ev, fn) => (handlers[id + ":" + ev] = fn) };
const ctx = vm.createContext({
  console, URLSearchParams, JSON, Math, Object, Promise, String, Array, Uint8Array, Int16Array, Float32Array, Blob: class {},
  location: { hash: "#token=t", protocol: "http:", host: "x", pathname: "/" }, history: { replaceState() {} },
  localStorage: { setItem() {}, getItem() {}, removeItem() {} }, prompt: () => "t", addEventListener() {},
  performance: { now: () => now }, btoa, atob, URL: { createObjectURL() {} },
  setTimeout() {}, setInterval: (fn) => { const id = nextId++; timers.set(id, fn); return id; },
  clearInterval: (id) => timers.delete(id),
  WebSocket: class { constructor() { this.readyState = 1; } send(m) { sent.push(JSON.parse(m)); } },
  document: {
    getElementById: el, activeElement: null,
    createElement: (tag) => tag === "canvas"
      ? { getContext: () => ({ drawImage() {} }), toDataURL: (t, q) => { assert.equal(q, 0.8); return "data:image/jpeg;base64," + screen; } }
      : { play: async () => {}, videoWidth: 2560, videoHeight: 1600 },
  },
  navigator: { mediaDevices: { getDisplayMedia: async () => ({ getVideoTracks: () => [track = {}] }) } },
});
vm.runInContext(src, ctx);
const run = (code) => vm.runInContext(code, ctx);
const tick = () => [...timers.values()].forEach((f) => f());
const grab = () => { now += 2000; handlers["sendScreen:click"](); return sent.at(-1); };
const logText = () => els.log.textContent.trim().split("\n").at(-1);

(async () => {
  // Not sharing: no timer, nothing sent.
  assert.equal(timers.size, 0); handlers["sendScreen:click"](); assert.equal(sent.length, 0);
  await handlers["share:click"](); assert.equal(timers.size, 1);

  // Still screen costs nothing; distinct frames are capped at 9, oldest dropped.
  for (let i = 0; i < 5; i++) tick(); assert.deepEqual(run("ring"), ["A"]);
  for (let i = 0; i < 15; i++) { screen = "F" + i; tick(); tick(); }
  assert.deepEqual(run("ring"), ["F6","F7","F8","F9","F10","F11","F12","F13","F14"]);

  // Question: data = fresh frame, newest ring frame equal to it is left out, oldest first, ring emptied.
  let m = grab();
  assert.equal(m.data, "F14"); assert.deepEqual(m.recent, ["F6","F7","F8","F9","F10","F11","F12","F13"]);
  assert.deepEqual(run("ring"), []); assert.match(logText(), /^screen frame sent \(button, 1280x800, 8 earlier, \d+ KB\)$/);

  // Ring empty -> no recent key at all.
  m = grab(); assert.equal(m.data, "F14"); assert.ok(!("recent" in m)); assert.match(logText(), /0 earlier/);

  // Fresh frame differs from ring -> whole ring goes.
  screen = "G"; tick(); screen = "H"; m = grab(); assert.deepEqual(m.recent, ["G"]);

  // Throttle unchanged: a second grab within 1500 ms sends nothing and keeps the ring.
  screen = "I"; tick(); const n = sent.length; now += 1000; handlers["sendScreen:click"]();
  assert.equal(sent.length, n); assert.deepEqual(run("ring"), ["I"]);

  // 8 MB total: oldest earlier frames are dropped first.
  const big = (c) => c.repeat(1398102); // ~1 MiB decoded each
  for (const c of "abcdefghij") { screen = big(c); tick(); }
  screen = big("z"); m = grab();
  const total = [m.data, ...m.recent].reduce((s, d) => s + d.length * 0.75, 0);
  assert.ok(total <= 8 << 20, total); assert.equal(m.recent.at(-1)[0], "j"); assert.equal(m.recent.length, 6);

  // Sharing ends: timer stopped, ring cleared.
  screen = "K"; tick(); assert.equal(run("ring").length, 1);
  track.onended(); assert.equal(timers.size, 0); assert.deepEqual(run("ring"), []);

  // Re-share: exactly one timer.
  await handlers["share:click"](); await handlers["share:click"](); assert.equal(timers.size, 1);
  console.log("RING CHECK OK");
})().catch((e) => { console.error(e); process.exit(1); });
